package io.coolbox.timer;
import static org.junit.jupiter.api.Assertions.*; import java.util.concurrent.atomic.AtomicReference; import org.junit.jupiter.api.Test;
class TimerTest { @Test void stopwatchAndScopeCallback(){try(Timer t=new Timer()){t.start();assertTrue(t.isRunning());assertTrue(t.lapMs()>=0);t.stop();assertFalse(t.isRunning());t.reset();assertEquals(0,t.elapsedMs());} AtomicReference<Double> sample=new AtomicReference<>();ScopedTimer scoped=new ScopedTimer(sample::set);assertTrue(scoped.elapsedMs()>=0);scoped.close();assertNotNull(sample.get());assertThrows(IllegalStateException.class,scoped::elapsedMs);try(TimingStats stats=new TimingStats()){stats.recordNs(12);try(ScopedTimer scopedStats=new ScopedTimer(stats)){scopedStats.close();}assertEquals(2,stats.snapshot().count());assertTrue(stats.snapshot().totalNs()>=12);}try(ConcurrentTimingStats stats=new ConcurrentTimingStats()){stats.recordNs(20);assertEquals(20,stats.snapshot().meanNs());}TimingSnapshot snapshot=new TimingSnapshot(2,10,3,7);assertEquals(5,snapshot.meanNs());} }
